import Model from 'flarum/common/Model';
/** A player, as `/api/roster-players` serves him. */
export default class Player extends Model {
  name = (() => Model.attribute('name'))();
  firstName = (() => Model.attribute('firstName'))();
  lastName = (() => Model.attribute('lastName'))();
  slug = (() => Model.attribute('slug'))();
  position = (() => Model.attribute('position'))();
  positionGroup = (() => Model.attribute('positionGroup'))();
  jersey = (() => Model.attribute('jersey'))();
  height = (() => Model.attribute('height'))();
  weight = (() => Model.attribute('weight'))();
  hometown = (() => Model.attribute('hometown'))();
  college = (() => Model.attribute('college'))();
  classYear = (() => Model.attribute('classYear'))();
  photo = (() => Model.attribute('photo'))();
  /** Only on his own page: what ESPN and Wikipedia have on him, and whether more is on its way. */
  profile = (() => Model.attribute('profile'))();
  team = (() => Model.hasOne('team'))();
}
flarum.reg.add('ernestdefoe-roster', 'forum/models/Player', Player);