import Model from 'flarum/common/Model';
/** A club, as `/api/roster-teams` serves it. */
export default class Team extends Model {
  name = (() => Model.attribute('name'))();
  slug = (() => Model.attribute('slug'))();
  mascot = (() => Model.attribute('mascot'))();
  abbreviation = (() => Model.attribute('abbreviation'))();
  conference = (() => Model.attribute('conference'))();
  /** The heading the index files it under: its conference, or a stand-in when it has none. */
  group = (() => Model.attribute('group'))();
  logo = (() => Model.attribute('logo'))();
  logoDark = (() => Model.attribute('logoDark'))();
  color = (() => Model.attribute('color'))();
  league = (() => Model.attribute('league'))();
  collegiate = (() => Model.attribute('collegiate'))();
  players = (() => Model.hasMany('players'))();
}
flarum.reg.add('ernestdefoe-roster', 'forum/models/Team', Team);